import { userAgent } from '../user-agent';

const webglBlacklist: string[] = [
    // Samsung Galaxy Tab 3, 8 inch
    'SM-T310', 'SM-T311', 'SM-T315',
    // Samsung Galaxy Tab 3 Lite
    'SM-T116',
    // Samsung Galaxy Tab E
    'SM-T560',
    // Samsung Galaxy S4
    'GT-I9505',
    // Samsung Galaxy J3 (2016)
    'SM-J320',
    // Samsung Galaxy J7
    'SM-J710F',
    // BQ Aquaris E5
    'Aquaris E5 HD',
    // Huawei P8 Lite
    'ALE-L21',
    // ZTE Blade L5
    'ZTE Blade L5'
];

// TODO: Determine if we still want to support Canvas at all going forward or just stick to WebGL
export function supportsWebGL(): boolean {
    const model = userAgent.device.model ?? 'NOMODEL';
  
    // force canvas if in blacklist
    if (webglBlacklist.indexOf(model) !== -1) {
        return false;
    }
  
    return true;
}